  gorsel: `<svg viewBox="0 0 560 280" role="img" aria-label="Sınıflara göre okunan kitap sayısı yatay çubuk grafiği"><text x="20" y="26" font-size="16" font-weight="bold" fill="currentColor">Grafik: Okuma yarışmasında okunan kitap sayısı</text><g stroke="currentColor" stroke-width="1" opacity="0.3"><line x1="140" y1="45" x2="140" y2="245"/><line x1="200" y1="45" x2="200" y2="245"/><line x1="260" y1="45" x2="260" y2="245"/><line x1="320" y1="45" x2="320" y2="245"/><line x1="380" y1="45" x2="380" y2="245"/><line x1="440" y1="45" x2="440" y2="245"/><line x1="500" y1="45" x2="500" y2="245"/></g><g stroke="currentColor" stroke-width="2"><line x1="80" y1="45" x2="80" y2="245"/><line x1="80" y1="245" x2="510" y2="245"/></g><text x="80" y="265" font-size="14" text-anchor="middle" fill="currentColor">0</text><text x="140" y="265" font-size="14" text-anchor="middle" fill="currentColor">10</text><text x="200" y="265" font-size="14" text-anchor="middle" fill="currentColor">20</text><text x="260" y="265" font-size="14" text-anchor="middle" fill="currentColor">30</text><text x="320" y="265" font-size="14" text-anchor="middle" fill="currentColor">40</text><text x="380" y="265" font-size="14" text-anchor="middle" fill="currentColor">50</text><text x="440" y="265" font-size="14" text-anchor="middle" fill="currentColor">60</text><text x="500" y="265" font-size="14" text-anchor="middle" fill="currentColor">70</text><rect x="80" y="55" width="240" height="30" fill="var(--dolgu)" stroke="var(--vurgu)" stroke-width="2"/><text x="328" y="75" font-size="15" font-weight="bold" fill="currentColor">40</text><text x="70" y="75" font-size="15" text-anchor="end" fill="currentColor">8-A</text><rect x="80" y="105" width="360" height="30" fill="var(--dolgu)" stroke="var(--vurgu)" stroke-width="2"/><text x="448" y="125" font-size="15" font-weight="bold" fill="currentColor">60</text><text x="70" y="125" font-size="15" text-anchor="end" fill="currentColor">8-B</text><rect x="80" y="155" width="210" height="30" fill="var(--dolgu)" stroke="var(--vurgu)" stroke-width="2"/><text x="298" y="175" font-size="15" font-weight="bold" fill="currentColor">35</text><text x="70" y="175" font-size="15" text-anchor="end" fill="currentColor">8-C</text><rect x="80" y="205" width="300" height="30" fill="var(--dolgu)" stroke="var(--vurgu)" stroke-width="2"/><text x="388" y="225" font-size="15" font-weight="bold" fill="currentColor">50</text><text x="70" y="225" font-size="15" text-anchor="end" fill="currentColor">8-D</text></svg>`,
